mapper.select:
select if(sum(if(black_gray_type = 'BLACK_LIST', 1, 0)) is null ,0, sum(if(black_gray_type = 'BLACK_LIST', 1, 0))) as black, if(sum(if(black_gray_type = 'GRAY_LIST', 1, 0)) is null ,0, sum(if(black_gray_type = 'GRAY_LIST', 1, 0))) as gray from black_gray_library bgl
1 = 1 and bgl.warehouse_time <= curdate() and bgl.plan_outbound_time >= curdate()
-- 处理列表根据机构隔离决定是否可见 and bgl.apply_time <= #{timePoint}
-- 处理列表根据机构隔离决定是否可见 and bgl.enterprise_name in
#{item}

select if(sum(if(black_gray_type = 'BLACK_LIST', 1, 0)) is null ,0, sum(if(black_gray_type = 'BLACK_LIST', 1, 0))) as black,if(sum(if(black_gray_type = 'GRAY_LIST', 1, 0)) is null ,0, sum(if(black_gray_type = 'GRAY_LIST', 1, 0))) as gray from black_gray_library bgl
1 = 1 and business_type = 'INFORMATION_RELATED' and bgl.warehouse_time <= curdate() and bgl.plan_outbound_time >= curdate()
-- 处理列表根据机构隔离决定是否可见 and bgl.apply_time <= #{timePoint}
-- 处理列表根据机构隔离决定是否可见 and bgl.enterprise_name in
#{item}

select b.industry_name,count(*) as number from (select REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(name,'[0-9]',''),'回租',''),'直租',''),'租赁','') AS name, industry_name from concentration_report where time_point = #{timePoint}) b inner join (select * from black_gray_library bgl
1 = 1 and black_gray_type = 'BLACK_LIST' and bgl.warehouse_time <= curdate() and bgl.plan_outbound_time >= curdate()
-- 处理列表根据机构隔离决定是否可见 and bgl.enterprise_name in
#{item}
) a on a.enterprise_name = b.name where b.industry_name is not null group by b.industry_name order by number desc

select b.industry_name,count(*) as number from (select distinct REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(name,'[0-9]',''),'回租',''),'直租',''),'租赁','') AS name,industry_name from concentration_report where time_point = #{timePoint}) b inner join (select * from black_gray_library bgl
1 = 1 and black_gray_type = 'BLACK_LIST' and business_type = 'INFORMATION_RELATED' and bgl.warehouse_time <= curdate() and bgl.plan_outbound_time >= curdate()
-- 处理列表根据机构隔离决定是否可见 and bgl.enterprise_name in
#{item}
) a on a.enterprise_name = b.name where b.industry_name is not null group by b.industry_name order by number desc

select b.industry_name,count(*) as number from (select REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(name,'[0-9]',''),'回租',''),'直租',''),'租赁','') AS name,industry_name from concentration_report where time_point = #{timePoint}) b inner join (select * from black_gray_library bgl
1 = 1 and black_gray_type = 'GRAY_LIST' and bgl.warehouse_time <= curdate() and bgl.plan_outbound_time >= curdate()
-- 处理列表根据机构隔离决定是否可见 and bgl.enterprise_name in
#{item}
) a on a.enterprise_name = b.name where b.industry_name is not null group by b.industry_name order by number desc

select b.industry_name,count(*) as number from (select REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(name,'[0-9]',''),'回租',''),'直租',''),'租赁','') AS name,industry_name from concentration_report where time_point = #{timePoint}) b inner join (select * from black_gray_library bgl
1 = 1 and black_gray_type = 'GRAY_LIST' and business_type = 'INFORMATION_RELATED' and bgl.warehouse_time <= curdate() and bgl.plan_outbound_time >= curdate()
-- 处理列表根据机构隔离决定是否可见 and bgl.enterprise_name in
#{item}
) a on a.enterprise_name = b.name where b.industry_name is not null group by b.industry_name order by number desc

# 企业维度 select t2.*, bo.`name` as orgName from ( SELECT apply_organization as orgCode, SUM(IF(black_gray_type_num=2,1,0)) as blackCount, SUM(IF(black_gray_type_num=1,1,0)) as grayCount FROM ( SELECT MAX(black_gray_type_num) AS black_gray_type_num, apply_organization FROM black_gray_library WHERE stock_status = 0 and (source = 'EXTERNAL_UPLOAD' or (source !='EXTERNAL_UPLOAD' AND share_type = 0))
AND business_type = #{businessType}
GROUP BY apply_organization, enterprise_name ) AS t1 WHERE black_gray_type_num IN ( 1, 2 ) GROUP BY apply_organization ) as t2 inner join bifrost_org bo on bo.`code` = t2.orgCode

SELECT CASE black_gray_type_num WHEN 2 THEN 'BLACK_LIST' WHEN 1 THEN 'GRAY_LIST' END AS black_gray_type, COUNT(1) AS cnt FROM ( SELECT MAX(black_gray_type_num) AS black_gray_type_num FROM black_gray_library WHERE stock_status = 0 and (source = 'EXTERNAL_UPLOAD' or (source !='EXTERNAL_UPLOAD' AND share_type = 0))
AND business_type = #{businessType}
GROUP BY enterprise_name ) AS t2 WHERE black_gray_type_num IN ( 1, 2 ) GROUP BY black_gray_type_num

select bgl.id, bgl.unified_social_credit_code, bgl.enterprise_name,
IF(MAX(bgl.black_gray_type_num)=2, 'BLACK_LIST', 'GRAY_LIST') as black_gray_type
from black_gray_library bgl
where stock_status = 0
  and (source = 'EXTERNAL_UPLOAD' or (source !='EXTERNAL_UPLOAD' AND share_type = 0))


    and bgl.id in
    
        {item}
    


    and bgl.unified_social_credit_code = #{req.unifiedSocialCreditCode}


    and bgl.enterprise_name = #{req.enterpriseName}


    and bgl.business_type = #{req.businessType}


    and bgl.apply_organization in
    
        #{item}
    

group by bgl.enterprise_name
order by bgl.update_time desc, bgl.id desc

select t.*, IF(t.black_gray_type_num=2,'BLACK_LIST','GRAY_LIST') as black_gray_type from ( select id,membership_group as groupName, group_credit_code, max(Update_Time) as update_time, MAX(black_gray_type_num) as black_gray_type_num from black_gray_library where group_leader_flag = 1 and stock_status = 0 and (source = 'EXTERNAL_UPLOAD' or (source !='EXTERNAL_UPLOAD' AND share_type = 0))
and membership_group in
#{item}
and (membership_group = #{req.groupNameCreditCode} or group_credit_code = #{req.groupNameCreditCode})
and business_type = #{req.businessType}
GROUP BY membership_group
)t order by t.update_time desc

select membership_group, count(DISTINCT enterprise_name) as entCount from black_gray_library where membership_group is not null and membership_group in
#{item}
and stock_status = 0 and enterprise_name is not NULL and group_leader_flag = 0 and (source = 'EXTERNAL_UPLOAD' or (source !='EXTERNAL_UPLOAD' AND share_type = 0))
and business_type = #{businessType}
GROUP BY membership_group

select black_gray_type
from black_gray_library
where
    unified_social_credit_code = #{getEnterpriseCode}
    
        and apply_organization = #{orgCode}
    
and warehouse_time <= curdate() and plan_outbound_time >= curdate() order by black_gray_type limit 1;
